patch('runtime-blueprint.mjs',"export function validateRuntimeBlueprint(blueprint,{complete=false,expectedBinding}={}){", "export function validateRuntimeBlueprint(blueprint,{complete=false,expectedBinding,verifiedProfile}={}){\n  const profile=recoveryProfileFor(expectedBinding,verifiedProfile);\n  if(NEW_SERVICES.some(s=>Object.hasOwn(blueprint?.compose?.services??{},s))){\n    assert.ok(profile,'No legacy interpretation of extended runtime');\n    assert.deepEqual(Object.keys(blueprint.compose.services).sort(),[...BASE_SERVICES,...NEW_SERVICES].sort());\n    for(const name of NEW_SERVICES){const s=blueprint.compose.services[name];assert.equal(s.image,profile.policy.newContainers[name].image);assert.equal(s.user,'1000:1000');assert.equal(s.restart,'no');assert.deepEqual(s.ports??[],[]);}\n  }")
