patch('replay-native-snapshot.mjs',"assert.notEqual(apiDenied.status,0);assert.match(apiDenied.stderr,/pg_hba.conf rejects connection/);", "assert.notEqual(apiDenied.status,0);assert.match(apiDenied.stderr,/pg_hba.conf rejects connection/);\n const profile=recoveryProfileFor(expectedBinding);\n for(const role of [...BACKEND_ROLES,...(profile?Object.values(PROFILE_ROLES):[])]){\n  const no=execute(['exec',target,'psql','-h','/tmp','-X','-Atq','-U',role,'-d','postgres','-c','select 1'],{allowFailure:true});assert.notEqual(no.status,0);assert.match(no.stderr,/pg_hba.conf rejects connection/);\n }\n if(profile)assert.equal(query(\"select rolcanlogin from pg_roles where rolname='ats_firewood_health';\"),'f');")
